const ABILITIES={
 ayman:[{name:'Vestige d’empire',damage:790,text:'Rallume son ancienne puissance et consomme ses vestiges pour renforcer l’attaque.'},{name:'Survivre à la nuit',heal:220,guard:220,cooldown:2,text:'Reprend des forces et s’abrite derrière un bouclier au prochain impact.'}],
 zg:[{name:'Décret du Fondateur',damage:780,text:'Frappe renforcée par la diversité de ton cercle.'},{name:'Ralliement du cercle',heal:180,target:'team',cooldown:2,text:'Restaure 180 PV à chacun des trois alliés au combat, ZG compris.'}],
 'zg-exile':[{name:'Lame des dunes',damage:850,text:'Une frappe qui fait progresser la Marche des dunes.'},{name:'Tempête de l’exil',damage:620,guard:150,cooldown:1,text:'Attaque puis gagne un bouclier de 150 PV.'}],
 'yanis-vs-zg':[{name:'Entaille maudite',damage:760,text:'Libère la charge de l’armure. Expose ensuite sa défense.'},{name:'Serment de fer',guard:300,charge:100,cooldown:1,text:'Referme la brèche, protège et charge l’armure de 100 ATK.'}],
 'yanis-soldat':[{name:'Tir de couverture',damage:650,guard:80,text:'Un tir prudent suivi d’un bouclier de 80 PV.'},{name:'Repli tactique',heal:180,guard:250,cooldown:2,text:'Se soigne et se met à couvert pour le prochain impact.'}],
 'abde-yanis':[{name:'Fracture temporelle',damage:700,text:'Libère les charges de temps : attaque renforcée et soin passif.'},{name:'Pause hors du temps',heal:240,target:'ally',cooldown:1,text:'Restaure 240 PV à un allié au combat et stocke une charge de temps (maximum 2).'}],
 'tom-samourai':[{name:'Coupe rosée',damage:780,text:'Consomme le Iaï préparé. Un type favorable déclenche son bouclier.'},{name:'Garde du sakura',guard:250,cooldown:1,text:'Protège Tom et prépare +250 ATK pour sa prochaine frappe.'}],
 'tom-u6':[{name:'Injection fulgurante',damage:720,text:'Consomme une dose disponible : +150 ATK et 100 PV soignés.'},{name:'Protocole U6',heal:360,target:'ally',cooldown:2,prepare:true,text:'Soigne un allié au combat de 360 PV et prépare 2 doses pour Tom (3 produites par duel maximum).'}],
 'emilien-larp':[{name:'Charge du Larp',damage:720,text:'Incarne le rôle Assaut (+200 ATK) et passe à l’action.'},{name:'Rempart de Carthage',guard:300,target:'ally',cooldown:1,text:'Incarne le Gardien (+250 DEF) et protège un allié au combat avec un bouclier de 300 PV.'}]
};
function abilitiesFor(c){if(!isPlayable(c))return [];return ABILITIES[c.id]||[{name:c.skill||('Frappe '+c.type.toLowerCase()),damage:650,text:'Une attaque du type de cette carte.'},{name:'Garde du cercle',guard:250,cooldown:1,text:'Un bouclier contre le prochain impact.'}];}
function abilityReady(c,index,ai=false){return Math.max(0,(battle?.cooldowns?.[(ai?'ai:':'')+c.id+':'+index]||0)-(battle?.turn||1));}
function moveDetails(c){const moves=abilitiesFor(c);if(!moves.length)return '';return `<section class="moves-detail"><div class="eyebrow">2 CAPACITÉS · 1 ACTION D’ÉQUIPE PAR TOUR</div>${moves.map(m=>`<div><span><b>${esc(m.name)}</b><small>${esc(m.text)}${m.cooldown?` Recharge : ${m.cooldown} tour(s).`:''}</small></span><strong>${m.damage?`${m.damage} base`:[m.heal?`+${m.heal} PV`:'',m.guard?`▱ ${m.guard}`:''].filter(Boolean).join(' · ')}</strong></div>`).join('')}<small>En duel, les dégâts sont ajustés à la cible et à ses protections.</small></section>`;}
